mapper.select:
select notice_seq, title, is_pinned, view_count, created_at, updated_at, writer_name
  from (
	select rownum as rnum, t.*
	  from (
		select n.notice_seq, n.title, n.is_pinned, n.view_count, n.created_at, n.updated_at,
		       m.nickname as writer_name
		  from notice n
		  left join member m on n.admin_seq = m.member_seq

		 order by case when n.is_pinned = 'Y' then 0 else 1 end, n.notice_seq desc
	  ) t
	 where rownum <= #{endRow}
  )
 where rnum >= #{startRow}
